def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The small colored pattern is a key: apply its colors to the large
    # tiled pattern by matching the 8-cell regions to the key's colors.
    # Determine the key colors in row-major order.
    key = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 8):
                key.append((r, c, grid[r][c]))
    colors = [x[2] for x in key]

    # Divide the large pattern into its rectangular connected components.
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    comps = []
    while unseen:
        start = unseen.pop()
        stack = [start]
        comp = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    stack.append(p)
                    comp.append(p)
        comps.append(comp)

    # Color each component according to its size and position relative to
    # the other components, using the key's row-major color sequence.
    comps.sort(key=lambda a: (min(r for r,c in a), min(c for r,c in a)))
    for i, comp in enumerate(comps):
        color = colors[i % len(colors)] if colors else 8
        for r, c in comp:
            out[r][c] = color
    return out
